/* -------------------------------------------------------------------------
   Cross-cutting explanatory text
   ------------------------------------------------------------------------- */
const RUN_CONCEPT_NOTE = "An analytical run is the interval or group of patient results over which a QC decision is made — for example, a shift, a calibration cycle, or a fixed number of patient samples. It is not necessarily equivalent to one calendar day, and its exact definition depends on the analytical system and the laboratory's own QC strategy.";

const CLASSIC_MODE_NOTE = "Classic warning-gated: 1₂s is used as a warning trigger. When it occurs, the traditional workflow calls for inspecting the rejection criteria (1₃s, 2₂s, R₄s, 4₁s, 10x) before deciding whether to reject the run.";
const DIRECT_MODE_NOTE = "Direct evaluation: every enabled rejection rule is evaluated directly, without requiring 1₂s to act as a gate. Computerized QC systems can do this in real time. Neither workflow is universally superior — they represent different, equally legitimate ways of organising the same underlying detection logic.";

const FALSE_REJECTION_NOTE = "Applying more QC rules can improve error detection, but may also increase the probability of falsely rejecting an analytical run that is not actually in error (false rejection). This trade-off is introduced here only qualitatively — this build does not calculate probability of error detection (Ped) or probability of false rejection (Pfr), and does not display operating-specification (OPSpecs) charts or recommend rule sets based on Sigma. Those belong to a later QC-design module.";

const DECISION_GUARDRAIL_NOTE = "A rule violation means exactly this: the mathematical condition for that rule was met by these observations. It does not, by itself, establish which analytical cause is responsible (for example calibration failure, reagent deterioration, pipetting error, or instrument malfunction), and it does not automatically invalidate patient results. Those judgements require investigation and belong to the laboratory's own QC procedure.";

const RULE_LAB_INTRO = "The Rule Laboratory teaches statistical QC rules by having you observe a QC sequence, identify which rule (if any) applies, locate exactly which observations caused it, understand whether it evaluates one run or spans several, and interpret what that pattern does and does not establish. It does not replace judgement about the underlying analytical cause.";
/* =========================================================================
   Rule Laboratory — UI components (multi-level LJ chart, event list)
   ========================================================================= */

function keyFor(runNumber, levelId) { return runNumber + ":" + levelId; }

/* Multi-level Levey-Jennings chart.
   Always plots vertical position from zScore (so two materials with
   different concentrations/units remain comparable on one chart); raw
   values remain fully inspectable via tooltip and the data table.
   Level identity is carried by BOTH shape (circle vs diamond) AND line
   style (solid vs dashed), never by colour alone. Point colour continues
   to encode severity (as in the single-level LJ Laboratory chart).
   selectedKeys: Set of "run:level" the learner has clicked (pre-commit).
   revealKeys: Set of "run:level" that actually triggered a rule
   (post-commit "reveal"); when provided, selectedKeys not in revealKeys
   are flagged as an incorrect pick. */
function MultiLevelLJChart({ runs, showL1, showL2, onPointClick, selectedKeys, revealKeys, eventAnnotationRun, decimals, unitMode }) {
  const [active, setActive] = useState(null);
  const W = 780, H = 400;
  const padL = 56, padR = 34, padT = 24, padB = 56;
  const plotW = W - padL - padR;
  const plotH = H - padT - padB;
  const dp = decimals != null ? decimals : 2;
  const n = runs.length;
  const xFor = i => padL + (n <= 1 ? plotW / 2 : (i / (n - 1)) * plotW);
  const domainSD = 4;
  const yForSD = z => padT + plotH / 2 - (z / domainSD) * (plotH / 2);
  const gridLevels = [-3, -2, -1, 0, 1, 2, 3];
  const runSpacing = n > 1 ? plotW / (n - 1) : plotW;
  const showAllRunLabels = runSpacing >= 22;
  const keyRuns = new Set([runs[0] ? runs[0].runNumber : 1, runs[n - 1] ? runs[n - 1].runNumber : n]);

  function seriesFor(levelId) {
    const pts = [];
    runs.forEach((run, i) => {
      const cr = (run.controlResults || []).find(c => c.levelId === levelId);
      if (cr) pts.push({ i, run, cr });
    });
    return pts;
  }
  const l1pts = seriesFor("L1");
  const l2pts = seriesFor("L2");

  function pathFor(pts) {
    return pts.map((p, idx) => (idx === 0 ? "M" : "L") + xFor(p.i).toFixed(2) + "," + yForSD(p.cr.zScore).toFixed(2)).join(" ");
  }

  function pointClass(z) {
    const az = Math.abs(z);
    if (az > 3) return "point-out";
    if (az > 2) return "point-warn";
    return "";
  }

  /* v0.9 accessibility fix (Stage 11B, AD-001): a single activation function
     so click, Enter, and Space all invoke identical semantics. The v0.8
     baseline had role="button"/tabIndex={0} with only onClick — keyboard-
     focusable but not keyboard-activatable (validated Stage 10F). This is
     an INTENDED v0.9 delta from that known limitation. */
  function activatePoint(runNumber, levelId) {
    const k = keyFor(runNumber, levelId);
    setActive(k);
    if (onPointClick) onPointClick(runNumber, levelId);
  }

  function renderSeries(pts, levelId, shape) {
    return pts.map(p => {
      const x = xFor(p.i), y = yForSD(p.cr.zScore);
      const k = keyFor(p.run.runNumber, levelId);
      const isActive = active === k;
      const isSelected = selectedKeys && selectedKeys.has(k);
      const isRevealCorrect = revealKeys && revealKeys.has(k);
      const isRevealWrongPick = revealKeys && isSelected && !isRevealCorrect;
      let ringClass = "";
      if (revealKeys) {
        if (isRevealCorrect) ringClass = "mlj-ring mlj-ring-correct";
        else if (isRevealWrongPick) ringClass = "mlj-ring mlj-ring-incorrect";
      } else if (isSelected) {
        ringClass = "mlj-ring mlj-ring-selected";
      }
      const r = isActive ? 7 : 5.5;
      return (
        <g key={k}
          onMouseEnter={() => setActive(k)}
          onFocus={() => setActive(k)}
          onClick={() => activatePoint(p.run.runNumber, levelId)}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
              e.preventDefault();
              activatePoint(p.run.runNumber, levelId);
            }
          }}
          tabIndex={0} role="button"
          aria-label={p.cr.levelName + ", run " + p.run.runNumber + ", value " + p.cr.rawValue.toFixed(dp) + ", " + p.cr.zScore.toFixed(2) + " SD"}
          className="mlj-point-g" style={{ cursor: onPointClick ? "pointer" : "default" }}>
          {ringClass && <circle cx={x} cy={y} r={r + 5} className={ringClass} fill="none" />}
          {shape === "circle"
            ? <circle cx={x} cy={y} r={r} className={"mlj-point mlj-point-l1 " + pointClass(p.cr.zScore)} />
            : <path d={diamondPath(x, y, r)} className={"mlj-point mlj-point-l2 " + pointClass(p.cr.zScore)} />}
        </g>
      );
    });
  }

  function diamondPath(cx, cy, r) {
    return `M ${cx} ${cy - r} L ${cx + r} ${cy} L ${cx} ${cy + r} L ${cx - r} ${cy} Z`;
  }

  const activePoint = (() => {
    if (!active) return null;
    for (const p of l1pts) if (keyFor(p.run.runNumber, "L1") === active) return { levelName: "Level 1", ...p };
    for (const p of l2pts) if (keyFor(p.run.runNumber, "L2") === active) return { levelName: "Level 2", ...p };
    return null;
  })();

  return (
    <div className="ljchart-wrap">
      <svg viewBox={"0 0 " + W + " " + H} className="ljchart-svg" role="img"
        aria-label={"Multi-level Levey-Jennings chart, " + n + " runs" + (showL1 && showL2 ? ", both levels shown" : showL1 ? ", Level 1 only" : ", Level 2 only")}>
        {gridLevels.map(lv => {
          const y = yForSD(lv);
          const label = lv === 0 ? "Mean" : (lv > 0 ? "+" + lv + " SD" : lv + " SD");
          return (
            <g key={lv}>
              <line x1={padL} x2={W - padR} y1={y} y2={y}
                className={lv === 0 ? "grid-line grid-mean" : (Math.abs(lv) === 3 ? "grid-line grid-3" : (Math.abs(lv) === 2 ? "grid-line grid-2" : "grid-line grid-1"))}
                strokeDasharray={lv === 0 ? "0" : (Math.abs(lv) === 3 ? "2 3" : "5 3")} />
              <text x={padL - 8} y={y + 4} textAnchor="end" className="axis-label-y">{label}</text>
            </g>
          );
        })}
        {eventAnnotationRun != null && runs.some(r => r.runNumber === eventAnnotationRun) && (
          <line x1={xFor(runs.findIndex(r => r.runNumber === eventAnnotationRun))} x2={xFor(runs.findIndex(r => r.runNumber === eventAnnotationRun))} y1={padT} y2={H - padB} className="event-line" />
        )}
        {showL1 && <path d={pathFor(l1pts)} className="mlj-line mlj-line-l1" fill="none" />}
        {showL2 && <path d={pathFor(l2pts)} className="mlj-line mlj-line-l2" fill="none" />}
        {showL1 && renderSeries(l1pts, "L1", "circle")}
        {showL2 && renderSeries(l2pts, "L2", "diamond")}
        {runs.map((run, i) => {
          const isKey = keyRuns.has(run.runNumber) || i === 0 || i === n - 1;
          if (!isKey && !showAllRunLabels) return null;
          const x = xFor(i);
          return (
            <g key={"t" + i}>
              <line x1={x} x2={x} y1={H - padB} y2={H - padB + 4} className={isKey ? "run-tick run-tick-key" : "run-tick"} />
              <text x={x} y={H - padB + 15} textAnchor="middle" className={isKey ? "axis-label-x axis-label-x-key" : "axis-label-x"}>{run.runNumber}</text>
            </g>
          );
        })}
        <text x={padL + plotW / 2} y={H - 8} textAnchor="middle" className="axis-title">Run number</text>
        <text x={16} y={padT + plotH / 2} textAnchor="middle" className="axis-title" transform={"rotate(-90 16 " + (padT + plotH / 2) + ")"}>QC value (SD units)</text>
      </svg>

      <div className="mlj-legend">
        <span className="mlj-legend-item"><svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="5" className="mlj-point mlj-point-l1" /></svg> Level 1 — solid line</span>
        <span className="mlj-legend-item"><svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d={diamondPath(7, 7, 5)} className="mlj-point mlj-point-l2" /></svg> Level 2 — dashed line</span>
        {revealKeys && <span className="mlj-legend-item"><span className="mlj-ring-sample mlj-ring-correct" /> Rule-triggering observation</span>}
        {revealKeys && <span className="mlj-legend-item"><span className="mlj-ring-sample mlj-ring-incorrect" /> Selected, not part of trigger</span>}
        {!revealKeys && onPointClick && <span className="mlj-legend-item"><span className="mlj-ring-sample mlj-ring-selected" /> Your selection</span>}
      </div>

      <div className="ljchart-tooltip" aria-live="polite">
        {activePoint ? (
          unitMode === "raw" ? (
            <span><strong>{activePoint.levelName}, run {activePoint.run.runNumber}:</strong> raw value {activePoint.cr.rawValue.toFixed(dp)} ({activePoint.cr.zScore >= 0 ? "+" : ""}{activePoint.cr.zScore.toFixed(2)} SD)</span>
          ) : (
            <span><strong>{activePoint.levelName}, run {activePoint.run.runNumber}:</strong> {activePoint.cr.zScore >= 0 ? "+" : ""}{activePoint.cr.zScore.toFixed(2)} SD (raw value {activePoint.cr.rawValue.toFixed(dp)})</span>
          )
        ) : (
          <span className="muted">Click or focus a point to inspect its run number, raw value and SD position.</span>
        )}
      </div>
      <p className="muted small">Point position on this chart is always plotted in SD units, so Level 1 and Level 2 remain comparable on one shared axis even if their raw concentrations differ. The raw / SD toggle below changes which value the table and tooltips lead with.</p>

      <details className="ljchart-table-details">
        <summary>Show data table (text alternative)</summary>
        <div className="table-scroll">
          <table className="data-table">
            <thead><tr><th>Run</th><th>Level 1 ({unitMode === "raw" ? "raw" : "SD"})</th><th>Level 2 ({unitMode === "raw" ? "raw" : "SD"})</th></tr></thead>
            <tbody>
              {runs.map(run => {
                const c1 = (run.controlResults || []).find(c => c.levelId === "L1");
                const c2 = (run.controlResults || []).find(c => c.levelId === "L2");
                function cell(c) {
                  if (!c) return "—";
                  return unitMode === "raw" ? c.rawValue.toFixed(dp) : (c.zScore >= 0 ? "+" : "") + c.zScore.toFixed(dp);
                }
                return (
                  <tr key={run.runNumber}>
                    <td>{run.runNumber}</td>
                    <td className={c1 && Math.abs(c1.zScore) > 3 ? "row-out" : c1 && Math.abs(c1.zScore) > 2 ? "row-warn" : ""}>{cell(c1)}</td>
                    <td className={c2 && Math.abs(c2.zScore) > 3 ? "row-out" : c2 && Math.abs(c2.zScore) > 2 ? "row-warn" : ""}>{cell(c2)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </details>
    </div>
  );
}

const SCOPE_LABELS = {
  "single-measurement": "Single measurement",
  "within-run-across-materials": "Within one run, across materials",
  "within-material-across-runs": "Within one material, across runs",
  "across-materials-and-runs": "Across materials and runs"
};

/* One detected event, with an expandable "Why?" explanation. */
function EventCard({ event }) {
  const [open, setOpen] = useState(false);
  return (
    <div className={"event-card event-card-" + event.status}>
      <div className="event-card-head">
        <span className="event-rule-label">{event.ruleLabel}</span>
        <Badge tone={event.status === "warning" ? "warn-badge" : "rejection-badge"}>{event.status === "warning" ? "Warning" : "Rejection criterion"}</Badge>
        <span className="muted small">{SCOPE_LABELS[event.scope]}</span>
      </div>
      <div className="event-card-meta">
        <span>Run{event.runNumbers.length > 1 ? "s" : ""}: {event.runNumbers.join(", ")}</span>
        <span>Material{event.controlLevels.length > 1 ? "s" : ""}: {event.controlLevels.map(l => l === "L1" ? "Level 1" : "Level 2").join(", ")}</span>
        <span>Direction: {event.direction}</span>
      </div>
      <button className="btn-link" onClick={() => setOpen(o => !o)}>{open ? "Hide" : "Why?"}</button>
      {open && <p className="event-why">{event.educationalInterpretation}</p>}
    </div>
  );
}
/* =========================================================================
   Rule Laboratory — screen: three internal modes (Learn the Rules,
   Inspect a QC Sequence, Rule Detective). All detection is delegated to
   07-rules.js; nothing in this file recomputes or hand-codes a "correct"
   answer that isn't cross-checked against the live engine.
   ========================================================================= */

const RULE_LAB_MODES = [
  { id: "learn", label: "Learn the Rules" },
  { id: "inspect", label: "Inspect a QC Sequence" },
  { id: "detective", label: "Rule Detective" }
];

function setsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const x of a) if (!b.has(x)) return false;
  return true;
}

/* ---------------------------- LEARN THE RULES ---------------------------- */
function LearnRulesPanel() {
  const [ruleId, setRuleId] = useState(RULE_DEFINITIONS[0].id);
  const [revealed, setRevealed] = useState(false);
  const rule = RULE_DEFINITIONS.find(r => r.id === ruleId);
  const events = useMemo(() => evaluateRuleSet(rule.demoRuns, [rule.id]), [ruleId]);
  const revealKeys = useMemo(() => {
    if (!revealed) return null;
    const s = new Set();
    events.forEach(e => e.triggerPoints.forEach(p => s.add(keyFor(p.runNumber, p.levelId))));
    return s;
  }, [revealed, events]);

  function selectRule(id) { setRuleId(id); setRevealed(false); }

  return (
    <div>
      <p className="muted">Select a rule to see its definition and an original, small demonstration dataset (not a reproduction of any proprietary Westgard chart), then run the actual detector against it.</p>
      <div className="tabbar" role="tablist" aria-label="Select a rule to learn">
        {RULE_DEFINITIONS.map(r => (
          <button key={r.id} role="tab" aria-selected={r.id === ruleId}
            className={"tab" + (r.id === ruleId ? " tab-active" : "")}
            onClick={() => selectRule(r.id)}>{r.label}</button>
        ))}
      </div>

      <div className="rule-detail-panel">
        <div className="rule-detail-head">
          <h2>{rule.label}</h2>
          <Badge tone={rule.status === "warning" ? "warn-badge" : "rejection-badge"}>{rule.status === "warning" ? "Warning criterion" : "Rejection criterion"}</Badge>
        </div>
        <dl className="evidence-fields">
          <dt>Definition</dt><dd>{rule.definition}</dd>
          <dt>Scope</dt><dd>{rule.scope}</dd>
          <dt>Typical interpretation</dt><dd>{rule.typicalInterpretation}</dd>
          <dt>What it does NOT tell you</dt><dd>{rule.whatItDoesNotTellYou}</dd>
          {rule.configurationNote && <><dt>Relation to N×R configuration</dt><dd>{rule.configurationNote}</dd></>}
        </dl>

        <MultiLevelLJChart runs={rule.demoRuns} showL1={true} showL2={true} revealKeys={revealKeys} decimals={2} />

        <div className="btn-row">
          {!revealed
            ? <button className="btn-primary" onClick={() => setRevealed(true)}>Run detection</button>
            : <button className="btn-secondary" onClick={() => setRevealed(false)}>Hide detected events</button>}
        </div>

        {revealed && (
          events.length
            ? events.map((e, i) => <EventCard key={rule.id + i} event={e} />)
            : <p className="event-list-empty">No {rule.label} violation is present in this demonstration dataset.</p>
        )}
      </div>
    </div>
  );
}

/* ---------------------------- INSPECT A QC SEQUENCE ---------------------------- */
function InspectSequencePanel({ markProgress }) {
  const [enabled, setEnabled] = useState(() => {
    const o = {}; RULE_ORDER.forEach(id => { o[id] = true; }); return o;
  });
  const [workflow, setWorkflow] = useState("classic");
  const [showL1, setShowL1] = useState(true);
  const [showL2, setShowL2] = useState(true);
  const [unitMode, setUnitMode] = useState("z");
  const [touched, setTouched] = useState(false);

  useEffect(() => { if (touched) markProgress("rules"); }, [touched]);

  const enabledRuleIds = RULE_ORDER.filter(id => enabled[id]);
  const events = useMemo(() => evaluateRuleSet(INSPECTOR_DEFAULT_RUNS, enabledRuleIds), [enabled]);
  const warningEvents = events.filter(e => e.status === "warning");
  const rejectionEvents = events.filter(e => e.status === "rejection");
  const warningRuns = new Set(warningEvents.flatMap(e => e.runNumbers));

  function toggleRule(id) { setEnabled(e => ({ ...e, [id]: !e[id] })); setTouched(true); }

  return (
    <div>
      <p className="muted">One deterministic 20-run, two-level sequence for free exploration. Toggle rules on or off, compare the classic and direct workflows, and inspect any point on the chart. Nothing here infers a root cause automatically.</p>

      <div className="control-row">
        <div className="control-group">
          <span className="control-group-label">Enabled rules</span>
          <div className="checkbox-row">
            {RULE_ORDER.map(id => (
              <label key={id}>
                <input type="checkbox" checked={!!enabled[id]} onChange={() => toggleRule(id)} />
                {RULE_LABELS[id]}
              </label>
            ))}
          </div>
        </div>
        <div className="control-group">
          <span className="control-group-label">Evaluation workflow</span>
          <div className="segmented">
            <button className={"seg" + (workflow === "classic" ? " seg-active" : "")} onClick={() => { setWorkflow("classic"); setTouched(true); }}>Classic (warning-gated)</button>
            <button className={"seg" + (workflow === "direct" ? " seg-active" : "")} onClick={() => { setWorkflow("direct"); setTouched(true); }}>Direct evaluation</button>
          </div>
        </div>
        <div className="control-group">
          <span className="control-group-label">Chart units</span>
          <div className="segmented">
            <button className={"seg" + (unitMode === "z" ? " seg-active" : "")} onClick={() => setUnitMode("z")}>SD units</button>
            <button className={"seg" + (unitMode === "raw" ? " seg-active" : "")} onClick={() => setUnitMode("raw")}>Raw value</button>
          </div>
        </div>
      </div>

      <div className="level-toggles">
        <label><input type="checkbox" checked={showL1} onChange={e => setShowL1(e.target.checked)} /> Show Level 1</label>
        <label><input type="checkbox" checked={showL2} onChange={e => setShowL2(e.target.checked)} /> Show Level 2</label>
      </div>

      <MultiLevelLJChart runs={INSPECTOR_DEFAULT_RUNS} showL1={showL1} showL2={showL2} unitMode={unitMode} decimals={2} />

      <h3>Detected events ({events.length})</h3>
      {workflow === "classic" ? (
        <>
          <p className="callout-inline">{CLASSIC_MODE_NOTE}</p>
          <h4>Step 1 — warning signals (1₂s)</h4>
          {warningEvents.length
            ? warningEvents.map((e, i) => <EventCard key={"w" + i} event={e} />)
            : <p className="event-list-empty">No 1₂s warning is present with the currently enabled rules.</p>}
          <h4>Step 2 — rejection criteria inspected as a result</h4>
          {rejectionEvents.length ? rejectionEvents.map((e, i) => (
            <div key={"r" + i}>
              <EventCard event={e} />
              {!e.runNumbers.some(rn => warningRuns.has(rn)) && (
                <p className="muted small">This rejection-rule violation is mathematically present even though no 1₂s warning occurred in the same run — the underlying calculation is identical regardless of which workflow is used to look for it.</p>
              )}
            </div>
          )) : <p className="event-list-empty">No rejection-rule violation is present with the currently enabled rules.</p>}
        </>
      ) : (
        <>
          <p className="callout-inline">{DIRECT_MODE_NOTE}</p>
          {events.length
            ? events.map((e, i) => <EventCard key={"d" + i} event={e} />)
            : <p className="event-list-empty">No rule violation is detected with the currently enabled rules.</p>}
        </>
      )}
    </div>
  );
}

/* ---------------------------- RULE DETECTIVE ---------------------------- */
const DEFAULT_DETECTIVE_ANSWER = { rules: [], points: null, scope: null, confidence: null, submitted: false };

function RuleDetectivePanel({ level, markProgress }) {
  const [idx, setIdx] = useState(0);
  const [answers, setAnswers] = useState({});
  const kase = DETECTIVE_CASES[idx];
  const ans = answers[kase.id] || DEFAULT_DETECTIVE_ANSWER;
  const points = ans.points || new Set();

  const allSubmitted = DETECTIVE_CASES.every(c => answers[c.id] && answers[c.id].submitted);
  useEffect(() => { if (allSubmitted) markProgress("rules"); }, [allSubmitted]);

  function updateAns(patch) {
    setAnswers(a => ({ ...a, [kase.id]: { ...ans, points, ...patch } }));
  }

  const isNoneSelected = ans.rules.length === 1 && ans.rules[0] === "none";

  function toggleRuleChoice(id) {
    if (ans.submitted) return;
    let rules;
    if (id === "none") {
      rules = ans.rules.includes("none") ? [] : ["none"];
    } else {
      rules = ans.rules.filter(r => r !== "none");
      rules = rules.includes(id) ? rules.filter(r => r !== id) : rules.concat([id]);
    }
    updateAns({ rules, points: new Set(), scope: null });
  }

  function togglePoint(runNumber, levelId) {
    if (ans.submitted || isNoneSelected || ans.rules.length === 0) return;
    const k = keyFor(runNumber, levelId);
    const next = new Set(points);
    if (next.has(k)) next.delete(k); else next.add(k);
    updateAns({ points: next });
  }

  function chooseScope(id) {
    if (ans.submitted) return;
    updateAns({ scope: id });
  }
  function chooseConfidence(id) {
    if (ans.submitted) return;
    updateAns({ confidence: id });
  }

  const canSubmit = ans.rules.length > 0 && ans.confidence &&
    (isNoneSelected || (ans.scope && points.size > 0));

  function submit() {
    if (!canSubmit) return;
    updateAns({ submitted: true });
  }

  /* Ground truth is derived live from the actual engine restricted to the
     pedagogically-intended rule(s) for this case — never hand-typed. */
  const correctRuleId = kase.correctRules[0] === "none" ? null : kase.correctRules[0];
  const truthEvents = useMemo(() => correctRuleId ? evaluateRuleSet(kase.runs, [correctRuleId]) : [], [kase.id]);
  const truthKeys = useMemo(() => {
    const s = new Set();
    truthEvents.forEach(e => e.triggerPoints.forEach(p => s.add(keyFor(p.runNumber, p.levelId))));
    return s;
  }, [truthEvents]);

  const rulesSorted = ans.rules.slice().sort();
  const correctRulesSorted = kase.correctRules.slice().sort();
  const ruleCorrect = JSON.stringify(rulesSorted) === JSON.stringify(correctRulesSorted);
  const pointsCorrect = isNoneSelected ? points.size === 0 : setsEqual(points, truthKeys);
  const scopeCorrect = kase.correctScope === null ? true : ans.scope === kase.correctScope;
  const wasFullyCorrect = ans.submitted && ruleCorrect && pointsCorrect && scopeCorrect;

  const ruleScore = DETECTIVE_CASES.reduce((acc, c) => {
    const a = answers[c.id];
    if (!a || !a.submitted) return acc;
    return acc + (JSON.stringify(a.rules.slice().sort()) === JSON.stringify(c.correctRules.slice().sort()) ? 1 : 0);
  }, 0);
  const scopeScore = DETECTIVE_CASES.reduce((acc, c) => {
    const a = answers[c.id];
    if (!a || !a.submitted) return acc;
    const ok = c.correctScope === null ? true : a.scope === c.correctScope;
    return acc + (ok ? 1 : 0);
  }, 0);
  const pointScore = DETECTIVE_CASES.reduce((acc, c) => {
    const a = answers[c.id];
    if (!a || !a.submitted) return acc;
    const isNone = a.rules.length === 1 && a.rules[0] === "none";
    const cid = c.correctRules[0] === "none" ? null : c.correctRules[0];
    const tk = new Set();
    if (cid) evaluateRuleSet(c.runs, [cid]).forEach(e => e.triggerPoints.forEach(p => tk.add(keyFor(p.runNumber, p.levelId))));
    const ok = isNone ? (a.points ? a.points.size === 0 : true) : setsEqual(a.points || new Set(), tk);
    return acc + (ok ? 1 : 0);
  }, 0);
  const attemptedCount = DETECTIVE_CASES.filter(c => answers[c.id] && answers[c.id].submitted).length;

  const correctRuleLabel = correctRuleId
    ? (RULE_OPTIONS_FOR_CHALLENGE.find(o => o.id === correctRuleId) || {}).label
    : "No defined rule violation";
  const correctScopeLabel = kase.correctScope
    ? (SCOPE_OPTIONS_FOR_CHALLENGE.find(o => o.id === kase.correctScope) || {}).label
    : "Not applicable — no rule violation was identified";
  const whySatisfied = truthEvents.length
    ? truthEvents[0].educationalInterpretation
    : "No observation in this sequence exceeds any defined rule threshold, regardless of how the points are grouped.";

  return (
    <div>
      <p className="muted">Twelve deterministic cases. For each: (A) decide which rule, if any, applies; (B) click the actual observation(s) that trigger it on the chart; (C) classify its scope; (D) record your confidence; then commit for full feedback. Not every case contains a violation.</p>

      <div className="challenge-nav">
        {DETECTIVE_CASES.map((c, i) => (
          <button key={c.id} className={"case-chip" + (i === idx ? " case-chip-active" : "") + (answers[c.id] && answers[c.id].submitted ? " case-chip-done" : "")}
            onClick={() => setIdx(i)} aria-current={i === idx}>{c.id}</button>
        ))}
      </div>

      <div className="case-panel">
        <h2>Case {kase.id} of {DETECTIVE_CASES.length}</h2>

        <MultiLevelLJChart runs={kase.runs} showL1={true} showL2={true}
          onPointClick={togglePoint}
          selectedKeys={points}
          revealKeys={ans.submitted ? truthKeys : null}
          decimals={2} />

        <div className="question-block">
          <p className="q-prompt">A — Which rule, if any, applies?</p>
          <div className="option-list option-list-grid">
            {RULE_OPTIONS_FOR_CHALLENGE.map(o => (
              <button key={o.id} disabled={ans.submitted}
                className={"option-btn small" + (ans.rules.includes(o.id) ? " option-selected" : "")}
                onClick={() => toggleRuleChoice(o.id)}>{o.label}</button>
            ))}
          </div>
          <p className="muted small">More than one rule may apply at once; select all that do. Choosing "No defined rule violation" clears any other selection.</p>
        </div>

        {!isNoneSelected && ans.rules.length > 0 && (
          <div className="question-block">
            <p className="q-prompt">B — Click the actual triggering observation(s) on the chart above.</p>
            <p className="point-selection-hint">Selected: {points.size === 0 ? "none yet" : Array.from(points).join(", ")}</p>
          </div>
        )}

        {!isNoneSelected && ans.rules.length > 0 && (
          <div className="question-block">
            <p className="q-prompt">C — What is the scope of this pattern?</p>
            <div className="option-list option-list-grid">
              {SCOPE_OPTIONS_FOR_CHALLENGE.map(o => (
                <button key={o.id} disabled={ans.submitted}
                  className={"option-btn small" + (ans.scope === o.id ? " option-selected" : "")}
                  onClick={() => chooseScope(o.id)}>{o.label}</button>
              ))}
            </div>
          </div>
        )}
        {isNoneSelected && (
          <p className="detective-scope-note">Trigger-point selection and scope classification are not applicable — no rule violation was selected.</p>
        )}

        <div className="question-block">
          <p className="q-prompt">D — How confident are you in this interpretation?</p>
          <div className="option-list option-list-grid option-list-narrow">
            {CONFIDENCE_OPTIONS.map(o => (
              <button key={o.id} disabled={ans.submitted}
                className={"option-btn small" + (ans.confidence === o.id ? " option-selected" : "")}
                onClick={() => chooseConfidence(o.id)}>{o.label}</button>
            ))}
          </div>
          <p className="muted small">Confidence is recorded for reflection only — it does not change your score.</p>
        </div>

        {!ans.submitted ? (
          <button className="btn-primary" onClick={submit} disabled={!canSubmit}>Commit interpretation</button>
        ) : (
          <div className="feedback-panel">
            <h3>Feedback</h3>
            <p><strong>Your rule selection:</strong> {ans.rules.map(r => (RULE_OPTIONS_FOR_CHALLENGE.find(o => o.id === r) || {}).label).join(", ")} {ruleCorrect ? "— correct" : "— not the intended answer"}</p>
            <p><strong>Expected interpretation:</strong> {correctRuleLabel}</p>
            <p><strong>Triggering observations:</strong> {truthKeys.size ? Array.from(truthKeys).join(", ") : "None — no rule was triggered"} {pointsCorrect ? "(your selection matched)" : "(your selection did not fully match)"}</p>
            <p><strong>Why satisfied:</strong> {whySatisfied}</p>
            <p><strong>Why tempting alternatives are not satisfied:</strong> {kase.temptingAlternative}</p>
            <p><strong>Scope:</strong> {correctScopeLabel} {kase.correctScope ? (scopeCorrect ? "— correct" : "— not the intended answer") : ""}</p>
            <p><strong>What it suggests:</strong> {kase.whatItSuggests}</p>
            <p><strong>What it does not prove:</strong> {kase.whatItDoesNotProve}</p>
            <p><strong>On your confidence:</strong> {getConfidenceNote(ans.confidence, wasFullyCorrect)}</p>
            <div className="btn-row">
              {idx < DETECTIVE_CASES.length - 1 && <button className="btn-secondary" onClick={() => setIdx(idx + 1)}>Next case</button>}
              {idx > 0 && <button className="btn-link" onClick={() => setIdx(idx - 1)}>Previous case</button>}
            </div>
          </div>
        )}
      </div>

      <div className="score-summary">
        <h3>Session score ({attemptedCount} / {DETECTIVE_CASES.length} attempted)</h3>
        <div className="metric-row">
          <MetricCard label="Rule identification" value={ruleScore + " / " + DETECTIVE_CASES.length} />
          <MetricCard label="Trigger-point identification" value={pointScore + " / " + DETECTIVE_CASES.length} />
          <MetricCard label="Scope classification" value={scopeScore + " / " + DETECTIVE_CASES.length} />
        </div>
        {allSubmitted && <p className="muted">All cases attempted for this session. This score reflects a short prototype exercise and is not a competency certification.</p>}
      </div>
    </div>
  );
}

/* ---------------------------- SCREEN SHELL ---------------------------- */
function RuleLaboratoryScreen({ level, markProgress, goto }) {
  const [mode, setMode] = useState("learn");

  return (
    <div className="screen">
      <h1>Rule Laboratory</h1>
      <p className="muted">{RULE_LAB_INTRO}</p>
      <ScientificBasisNote goto={goto} text="Rule definitions and scopes reflect widely taught statistical QC concepts; see Evidence for CLSI C24 and Westgard-literature context and explicit non-endorsement statements." />
      <details className="basis-note">
        <summary>What is a "run"?</summary>
        <p>{RUN_CONCEPT_NOTE}</p>
      </details>

      <div className="tabbar" role="tablist" aria-label="Rule Laboratory mode">
        {RULE_LAB_MODES.map(m => (
          <button key={m.id} role="tab" aria-selected={mode === m.id}
            className={"tab" + (mode === m.id ? " tab-active" : "")}
            onClick={() => setMode(m.id)}>{m.label}</button>
        ))}
      </div>

      {mode === "learn" && <LearnRulesPanel />}
      {mode === "inspect" && <InspectSequencePanel markProgress={markProgress} />}
      {mode === "detective" && <RuleDetectivePanel level={level} markProgress={markProgress} />}

      <details className="important-note">
        <summary>About false rejection (qualitative only)</summary>
        <p className="muted small">{FALSE_REJECTION_NOTE}</p>
      </details>
      <div className="callout">{DECISION_GUARDRAIL_NOTE}</div>
    </div>
  );
}
/* =========================================================================
   core/opchar — validated operating-characteristic math (Ped / Pfr).

   Per the v0.3 spec, this application does NOT fabricate Ped/Pfr values and
   does NOT infer them from Sigma alone. It implements the "Alternative"
   scientifically-safe path: validated numerical calculations for a
   RESTRICTED SET of simple single-rule procedures only (here: 1_3s applied
   to N independent control measurements assumed Normally distributed),
   derived from standard normal-distribution theory and unit-tested against
   independently calculable reference values (standard normal table facts
   such as Phi(0)=0.5, Phi(3)=0.99865).

   For any multirule / sequential procedure (2_2s, R_4s, 4_1s, 10x and
   combinations of these), exact closed-form Ped/Pfr requires simulation
   that has not been independently validated in this build. Those
   procedures report { validated: false } and the UI must display:
   "Operating-characteristic estimate not implemented in this version."
   Nothing about their true operating characteristics is fabricated or
   inferred from Sigma. This module must never silently change that.

   PROVENANCE: Class A — directly recovered from recovery/original-v0.8.html
   (SHA-256: e5317bf135f350b258428b985c1034a081e244a295f2e580c93cb6a6a091c8e4)
   Source lines: ~4155-4282 (core/opchar section within app-source script)
   Historical reported v0.8 commit: 3cc62b1 (not independently verified)
   Recovery date: 2026-08-31
   ========================================================================= */

/* Abramowitz & Stegun 7.1.26 rational approximation to the error function,
   accurate to |error| <= 1.5e-7. Used to build the standard normal CDF. */
function erf(x) {
  const sign = x < 0 ? -1 : 1;
  x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741,
    a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const t = 1 / (1 + p * x);
  const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return sign * y;
}

/* Standard normal cumulative distribution function, P(Z <= z). */
function normalCDF(z) {
  return 0.5 * (1 + erf(z / Math.SQRT2));
}

/* Probability that a single control result, distributed N(0,1) under a
   stable (in-control) process, exceeds +3 SD or -3 SD (the 1_3s limit). */
function pfr1_3sSingle() {
  return 1 - (2 * normalCDF(3) - 1);
}

/* Probability of false rejection for the 1_3s rule applied independently
   to N control measurements in the stable-process case: at least one of N
   independent results exceeds +-3 SD. */
function pfr1_3s(N) {
  const pStayWithin = 2 * normalCDF(3) - 1;
  return 1 - Math.pow(pStayWithin, N);
}

/* Probability that a single control result detects a systematic shift of
   deltaSE standard-deviation units (the process mean has moved by
   deltaSE * SD) under the 1_3s rule: P(X > 3) + P(X < -3) for X ~ N(deltaSE, 1). */
function pedSingle1_3s(deltaSE) {
  return (1 - normalCDF(3 - deltaSE)) + normalCDF(-3 - deltaSE);
}

/* Probability of error detection for the 1_3s rule applied independently
   to N control measurements, given a systematic shift of deltaSE SD units:
   at least one of N independent results exceeds +-3 SD. */
function ped1_3s(deltaSE, N) {
  const pDetectSingle = pedSingle1_3s(deltaSE);
  return 1 - Math.pow(1 - pDetectSingle, N);
}

/* -------------------------------------------------------------------------
   v0.3.1 hardening (spec sections 7-8): operatingCharacteristic() must not
   appear to imply universal multirule support. The actual validated
   numerical method is now named explicitly — operatingCharacteristic13s()
   — and operatingCharacteristic(ruleIds, N, deltaSE) is a thin, safe
   DISPATCHER that calls it ONLY for the exact single-rule case ["13s"].
   Every other ruleIds combination (any multirule procedure, and any
   procedure containing 8x or 10x on its own) explicitly returns
   { supported: false, validated: false } with the exact required note
   text below — never a summed, multiplied, Sigma-inferred, or otherwise
   fabricated number. `validated` is retained alongside `supported` (same
   boolean) for backward compatibility with existing callers/tests.
   ------------------------------------------------------------------------- */
const UNSUPPORTED_OPCHAR_NOTE = "Numerical operating-characteristic calculation is not implemented for this multirule procedure in the current version.";
const UNSUPPORTED_OPCHAR_REASON = "Exact closed-form Ped/Pfr for a multirule or sequential procedure (for example 1₃s/2₂s/R₄s, 1₃s/2₂s/R₄s/4₁s, or any procedure including 8x or 10x) requires dedicated joint statistical modelling — simulation or derivation that has not been independently validated in this build. This application never adds individual rule probabilities together, multiplies them as though the rules were statistically independent, infers Ped/Pfr from Sigma alone, or otherwise approximates or fabricates a numeric value for an unvalidated procedure.";

/* The only independently validated numerical operating-characteristic
   calculation in this build: the single 1_3s rule applied on its own to N
   independent control measurements. */
function operatingCharacteristic13s(N, deltaSE) {
  if (typeof N !== "number" || !(N > 0)) return null;
  return {
    supported: true,
    validated: true,
    ruleId: "13s",
    N,
    deltaSE,
    pfr: pfr1_3s(N),
    ped: ped1_3s(deltaSE, N),
    basis: "Closed-form calculation from standard normal distribution theory (independent control measurements, Gaussian process assumption)."
  };
}

function unsupportedOperatingCharacteristic() {
  return { supported: false, validated: false, note: UNSUPPORTED_OPCHAR_NOTE, reason: UNSUPPORTED_OPCHAR_REASON };
}

/* Restricted validated operating-characteristic lookup, keyed by the same
   ruleId vocabulary used by the rule engine (07-rules.js). Only "13s" (used
   alone, with no other rule enabled) is validated in this build — this
   includes ruleIds arrays containing "8x" or "10x", alone or combined with
   any other rule, which always fall through to the unsupported branch. */
function operatingCharacteristic(ruleIds, N, deltaSE) {
  const onlyRule = Array.isArray(ruleIds) && ruleIds.length === 1 ? ruleIds[0] : null;
  if (onlyRule === "13s" && typeof N === "number" && N > 0) {
    return operatingCharacteristic13s(N, deltaSE);
  }
  return unsupportedOperatingCharacteristic();
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    erf, normalCDF,
    pfr1_3sSingle, pfr1_3s,
    pedSingle1_3s, ped1_3s,
    operatingCharacteristic13s, unsupportedOperatingCharacteristic,
    UNSUPPORTED_OPCHAR_NOTE, UNSUPPORTED_OPCHAR_REASON,
    operatingCharacteristic
  };
}
